/**
 * Project media, generated by scripts/gen-media.mjs into public/media/<slug>/.
 *
 * - poster: 16:10 at 640 and 1024 wide (AVIF and WebP). Decorative: the
 *   project's name is always beside it, so it carries alt="".
 * - preview: a moving version for the work index, played on hover only.
 * - film: the case page's moving figure. Its still (film-640/960) is the
 *   image in the HTML, with real alt text; the motion layer plays the animated
 *   WebP over it while it's in view and motion is on.
 * - stills: further 16:10 images for the case page, at 800 and 1280 wide.
 *
 * Captions describe only what the image shows. Every claim in them is visible
 * in the media itself.
 */
export type Film = { width: number; height: number; alt: string; caption: string }
export type Still = { name: string; alt: string; caption: string }

export type ProjectMedia = {
  poster: string
  preview?: { src: string; type: 'video/webm' | 'image/webp' }
  film?: Film
  stills?: Still[]
}

const posterBase = (slug: string) => `/media/${slug}/poster`

